import java.util.ArrayList;
import java.util.List;

public class Solution {
    interface ObservadorPedido {
        void aoMudarStatus(String pedidoId, String novoStatus);
    }

    static class Pedido {
        private final String id;
        private String status = "CRIADO";
        private final List<ObservadorPedido> observadores = new ArrayList<>();
        private final List<String> historico = new ArrayList<>(List.of("CRIADO"));
        private final List<String> falhas = new ArrayList<>();

        Pedido(String id) {
            if (id == null || id.isBlank()) throw new IllegalArgumentException("id obrigatorio");
            this.id = id;
        }

        void inscrever(ObservadorPedido observador) {
            if (observador == null) throw new IllegalArgumentException("observador obrigatorio");
            if (!observadores.contains(observador)) observadores.add(observador);
        }

        void desinscrever(ObservadorPedido observador) {
            observadores.remove(observador);
        }

        void mudarStatus(String novoStatus) {
            if (!transicaoValida(status, novoStatus)) {
                throw new IllegalStateException("transicao invalida: " + status + " -> " + novoStatus);
            }
            status = novoStatus;
            historico.add(novoStatus);
            for (var observador : List.copyOf(observadores)) {
                try {
                    observador.aoMudarStatus(id, novoStatus);
                } catch (RuntimeException e) {
                    falhas.add(observador.toString());
                }
            }
        }

        private boolean transicaoValida(String de, String para) {
            return switch (de) {
                case "CRIADO" -> para.equals("PAGO") || para.equals("CANCELADO");
                case "PAGO" -> para.equals("ENVIADO") || para.equals("CANCELADO");
                case "ENVIADO" -> para.equals("ENTREGUE");
                default -> false;
            };
        }

        String status() { return status; }
        List<String> historico() { return List.copyOf(historico); }
        List<String> notificacoesComFalha() { return List.copyOf(falhas); }
    }
}

