import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;

class SolutionTest {
    static class Espiao implements Solution.ObservadorPedido {
        final List<String> recebidos = new ArrayList<>();
        final String nome;
        Espiao(String nome) { this.nome = nome; }
        public void aoMudarStatus(String pedidoId, String novoStatus) {
            recebidos.add(pedidoId + ":" + novoStatus);
        }
        public String toString() { return nome; }
    }

    @Test void notificaNaOrdemDeInscricao() {
        var p = new Solution.Pedido("p1");
        var a = new Espiao("a");
        var b = new Espiao("b");
        p.inscrever(a);
        p.inscrever(b);
        p.mudarStatus("PAGO");
        assertEquals(List.of("p1:PAGO"), a.recebidos);
        assertEquals(List.of("p1:PAGO"), b.recebidos);
    }

    @Test void transicaoInvalidaNaoNotifica() {
        var p = new Solution.Pedido("p1");
        var a = new Espiao("a");
        p.inscrever(a);
        assertThrows(IllegalStateException.class, () -> p.mudarStatus("ENTREGUE"));
        assertEquals("CRIADO", p.status());
        assertTrue(a.recebidos.isEmpty());
        assertEquals(List.of("CRIADO"), p.historico());
    }

    @Test void observadorQueFalhaNaoBloqueiaOsOutros() {
        var p = new Solution.Pedido("p1");
        var ruim = new Solution.ObservadorPedido() {
            public void aoMudarStatus(String id, String s) { throw new RuntimeException("boom"); }
            public String toString() { return "ruim"; }
        };
        var bom = new Espiao("bom");
        p.inscrever(ruim);
        p.inscrever(bom);
        p.mudarStatus("PAGO");
        assertEquals("PAGO", p.status());
        assertEquals(List.of("p1:PAGO"), bom.recebidos);
        assertEquals(List.of("ruim"), p.notificacoesComFalha());
    }

    @Test void desinscricaoEDuplicata() {
        var p = new Solution.Pedido("p1");
        var a = new Espiao("a");
        p.inscrever(a);
        p.inscrever(a);
        p.mudarStatus("PAGO");
        assertEquals(1, a.recebidos.size());
        p.desinscrever(a);
        p.mudarStatus("ENVIADO");
        assertEquals(1, a.recebidos.size());
        assertEquals(List.of("CRIADO", "PAGO", "ENVIADO"), p.historico());
    }

    @Test void cancelamentoPermitido() {
        var p = new Solution.Pedido("p1");
        p.mudarStatus("PAGO");
        p.mudarStatus("CANCELADO");
        assertEquals("CANCELADO", p.status());
        assertThrows(IllegalStateException.class, () -> p.mudarStatus("ENVIADO"));
    }
}
